# StoryMap Variable Initialization Script
# ---------------------------------------------------------
class StoryMapVariables:
    def __init__(self, gis, username, county):
        self.portal_items = portal_items(gis=gis, username=username, county=county)
        
        # 1. Core County & Overview
        self.county = county
        self.image_url = "data:image/png;base64,"
        self.image_caption = ""
        wiki_text = crawl_wikipedia(county)
        self.overview_text1 = generate_overview(county, wiki_text)
        self.overview_image_url = "data:image/png;base64,"
        self.overview_image_caption = ""
        self.overview_map_id = self.portal_items[f"{self.county} County Overview Map"]


        # 2. Demographics
        self.demographics_map_id = self.portal_items[f"{self.county} County Socio-Demographic Map"]
        self.county_data = get_county_data(county)
        self.county_age_group = get_most_populous_age_group(county)
        self.median_age = self.county_data['median_age']
        self.age_range = self.county_age_group['age_group']
        self.education_percent = get_education_percent(county)["percent_bachelor_or_higher"]
        self.ethnicity_dict = max(
            {
                "White": self.county_data["percent_white"],
                "Black": self.county_data["percent_black"],
                "Asian": self.county_data["percent_asian"],
                "Native American": self.county_data["percent_native_american"],
                "Other": self.county_data["percent_other"],
            }.items(),
            key=lambda x: x[1]
        )
        self.ethnicity = self.ethnicity_dict[0]
        self.ethnicity_percent = self.ethnicity_dict[1]
        self.ethnicity_comparison = lambda: "higher" if self.ethnicity_percent > 72.3 and self.ethnicity == "White" else "lower"
        poverty_info = get_poverty_info(county)
        self.poverty_percent = poverty_info["poverty_percent"]
        self.tennessee_poverty_rate = 13.5
        self.poverty_comparison = lambda: "higher" if self.poverty_percent > self.tennessee_poverty_rate else "lower"
        self.poverty_age = poverty_info["most_prevalent_group"]
        self.disability_percent = get_disability_info(county)["disability_percent"]

        # 3. Employment
        labor_force_info = get_labor_force_info(county)
        labor_force_previous = get_labor_force_info(county, 2019)
        self.labor_force = labor_force_info["labor_force"]
        self.unemployment_rate = labor_force_info["unemployment_rate"]
        self.unemployment_pre = labor_force_previous["unemployment_rate"]
        self.unemployment_change = "incline" if self.unemployment_rate > self.unemployment_pre else "decline"
        self.unemployment_comparison_pre = "higher" if self.unemployment_change == "incline" else "lower"


        # 4. Commute
        self.commute_to = ["", "", ""]
        self.commute_to_count = [0, 0, 0]
        self.commute_from = ["", ""]

        # 5. Population Forecast
        self.population_forecast = county_population_trend(county,2026,2070)
        self.trend_text = TrendSummary(county=self.county,pop_dict=self.population_forecast['population_by_year']).trend_summary
        self.population_forecast_change = self.population_forecast['trend']
        self.population_forecast_map_id = self.portal_items[f"{self.county} County 2045 Population Forecast"]

        # 6. Land Use
        self.land_use_image_url = "data:image/png;base64,"
        self.land_use_image_caption = ""
        self.land_use_map_id = self.portal_items[f"{self.county} County Land Use"]

        # 7. Roadway & Functional Classification
        self.roadway_map_id = self.portal_items[f"{self.county} County Road Network"]
        self.functional_classification_map_id = self.portal_items[f"{self.county} County Functional Classification"]
        self.func_class = FuncClass(self.county)
        self.other_principal_arterials_miles = 0.0
        self.rural_minor_collectors_miles = 0.0
        self.rural_minor_arterials_miles = 0.0
        self.rural_major_collectors_miles = 0.0
        self.rural_local_roads_miles = 0.0

        # 8. Bridge Condition
        self.bridge_condition_map_id = self.portal_items[f"{self.county} County Bridge Conditions"]
        bridges = get_bridge_summary(county, f"https://services2.arcgis.com/nf3p7v7Zy4fTOh6M/arcgis/rest/services/Bridge_Condition/FeatureServer/0")
        bridge_count = bridges["Total"]
        good_condition_bridges = bridges['Good']
        fair_condition_bridges = bridges['Fair']
        poor_condition_bridges = bridges['Poor']
        critical_condition_bridges = bridges['Critical']
        self.bridge_count = bridge_count
        self.good_condition_bridges = good_condition_bridges
        self.fair_condition_bridges = fair_condition_bridges
        self.poor_condition_bridges = poor_condition_bridges
        self.critical_condition_bridges = critical_condition_bridges

        # 9. State-Aid Roads
        self.state_aid_road_map_id = self.portal_items[f"{self.county} County State-Aid Roads"]
        # self.state_aid_routes = self.func_class.get_state_aid_routes()
        self.state_aid_miles = self.func_class.state_aid_miles
        self.state_aid_count = self.func_class.state_aid_count
        # 10. Traffic Volume & Forecast
        self.current_traffic = TSMRetriever(self.county,"https://services2.arcgis.com/nf3p7v7Zy4fTOh6M/arcgis/rest/services/Tennessee_Statewide_Travel_Demand_Model/FeatureServer/3").tsm_features
        self.dominant_routes = ""
        self.dominant_route = ""
        self.dominant_direction = ""
        self.secondary_routes = ""
        self.traffic_volume_map_id = self.portal_items[f"{self.county} County 2024 Traffic"]
        self.forecast_traffic = TSMRetriever(self.county,"https://services2.arcgis.com/nf3p7v7Zy4fTOh6M/arcgis/rest/services/Tennessee_Statewide_Travel_Demand_Model/FeatureServer/6").tsm_features
        self.forecasted_increase = ""
        self.forecasted_routes = ""
        self.forecasted_traffic_volume_map_id = self.portal_items[f"{self.county} County 2045 Traffic Flow"]
        self.traffic_changes_routes = ""
        self.traffic_decrease_route = ""
        self.traffic_increase_route = ""
        self.traffic_changes_am_map_id = self.portal_items[f"{self.county} County Total AM Flow Change 2018-2045"]
        self.traffic_changes_pm_map_id = self.portal_items[f"{self.county} County Total PM Flow Change 2018-2045"]

        # 11. Truck Volume
        self.dominant_truck_routes = ""
        self.current_truck_volume_map_id = self.portal_items[f"{self.county} County 2018 Base Year Truck Volumes"]
        self.forecasted_truck_increase = ""
        self.primary_freight_route = ""
        self.primary_freight_direction = ""
        self.primary_freight_area = ""
        self.truck_volume_forecast_map_id = self.portal_items[f"{self.county} County Truck Volumes 2045 Forecast"]
        self.truck_flow_changes_map_id = self.portal_items[f"{self.county} County Truck Flow Changes 2018-2045"]

        # change
        self.traffic_change = ChangeRetriever(self.county)

        # 12. Vehicle Miles Traveled (VMT)
        self.highest_vmt_route = ""
        self.vehicle_miles_traveled_base_year_map_id = self.portal_items[f"{self.county} County VMT 2018 Base Year"]
        self.highest_vmt_forecast_route = ""
        self.vehicle_miles_traveled_forecast_map_id = self.portal_items[f"{self.county} County 2045 VMT Forecast Year"]
        self.highest_vmt_changes_route = ""
        self.vmt_changes_map_id = self.portal_items[f"{self.county} County Total VMT Changes 2018-2045"]

        # 13. Volume/Capacity Ratio
        self.number_of_congested_roads = 0
        self.highest_vc_ratio_route = ""
        self.vc_ratio_base_year_am_map_id = self.portal_items[f"{self.county} County 2018 AM VC Ratio"]
        self.vc_ratio_base_year_pm_map_id = self.portal_items[f"{self.county} County 2018 PM VC Ratio"]
        self.highest_vc_ratio_forecast_route = ""
        self.vc_ratio_forecast_am_map_id = self.portal_items[f"{self.county} County 2045 AM VC Ratio"]
        self.vc_ratio_forecast_pm_map_id = self.portal_items[f"{self.county} County 2045 PM VC Ratio"]

        # 14. Uniform Traffic Control Delay
        self.delayed_road = ""
        self.uniform_traffic_control_delay_map_id = self.portal_items[f"{self.county} County Forecast 2045 AB Delay"]

        # 15. Pavement Conditions
        pavement_retriever = PavementRetriever(self.county)
        self.pavement_condition_summary = pavement_retriever.pavement_summary
        self.pavement_condition_list = pavement_retriever.pavement_list
        self.pavement_condition = ""
        self.pavement_condition_routes = ""
        self.pavement_conditions_map_id = self.portal_items[f"{self.county} County Pavement Roughness"]

        # 16. Parks, Trails, Sidewalks, Bicycle
        self.greenway_and_parks = GreenwayandParksRetriever(self.county)
        self.parks_count = self.greenway_and_parks.parks_count
        self.trails_and_parks_map_id = self.portal_items[f"{self.county} County TREC Trails and Parks"]
        self.sidewalks_miles = SidewalkRetriever(self.county).sidewalk_miles
        self.sidewalks_map_id = self.portal_items[f"{self.county} County Sidewalks"]
        self.bicycle_ways_miles = BikeRetriever(self.county).bike_miles
        self.proposed_tennessee_designated_bicycle_routes_map_id = self.portal_items[f"{self.county} County Proposed State Bike Routes"]
        self.bicycle_corridors = ["", "", ""]
        self.bicycle_level_of_service_map_id = self.portal_items[f"{self.county} County Bicycle Level of Service"]

        # 17. Public Transit
        self.public_transit_provider = ""
        self.public_transit_coverage = ""
        self.public_transit_increase = 0.0
        self.public_transit_service = ""

        # 18. TDOT Projects
        self.project_number = 0
        self.pe_design_year = 0
        self.row_year = 0
        self.estimated_construction_year = 0
        self.estimated_cost = 0.0

        # 19. Crashes
        self.crash_features = CrashRetriever(self.county)       
        self.total_crashes = self.crash_features.total_crashes
        self.start_date = ""
        self.end_date = ""
        self.highest_crash_density_route = ", ".join([f"{r} ({c})" for r, c in self.crash_features.top_crash_routes])
        self.crash_density_map_id = self.portal_items[f"{self.county} County Crash Density"]
        self.bike_crash_features = BikeCrashRetriever(self.county)
        self.total_bicycle_crashes = self.bike_crash_features.total_bicycle_crashes
        self.total_pedestrian_crashes = self.bike_crash_features.total_pedestrian_crashes
        self.bicycle_and_pedestrian_crash_map_id = self.portal_items[f"{self.county} County Bicycle and Pedestrian Crashes (2015-2024)"]

        # 20. Stakeholder Survey
        self.county_stakeholder_survey_map_id = self.portal_items[f"{self.county} County Overview Map"]
        self.issue = ""
        self.answer = ""
        self.priority = ""

